// Self-contained mock data for the Audit Scope Management page. Like
// sub-division-static-data.ts / division-static-data.ts, this does NOT read
// `crowe_all_static_extended.json` at bootstrap — everything it renders is
// compiled into the bundle from here. Independently authored from those two
// files (same 8-company roster — ids/tags/colors — different division/scope
// records), matching the established per-module static-data pattern.
//
// Scopes can sit at two levels: directly under a division (`division.scopes`,
// `subDivisionName: null`, `subDivisionsInfo` = that division's sub-division
// codes) or under a sub-division (`subDivision.scopes`, `subDivisionsInfo: null`).
//
// Scopes and sub-scopes are NOT nested — they're a single flat `scopes[]`
// per division/sub-division, differentiated only by `parentScopeId` (null = top-level
// scope, set = sub-scope of that scope). This mirrors how the Add/Edit Audit
// Scope drawer actually creates them: the same form/tab is used for both,
// the only difference being whether a Parent Scope is selected. A scope
// whose own `parentScopeId` is set can never itself be a parent (enforced by
// `topLevelScopeOptionsForSubDivision`, which only ever lists parentless
// scopes) — sub-scopes cannot have sub-scopes.

import { AUDITOR_PROFILES, REVIEWER_PROFILES } from '@/app/features/audits/organization/divisions/divisions-list/divisions-list.component';
import { DIVISION_STATIC_COMPANIES } from '@/app/features/audits/organization/divisions/division-static-data';
import { SUB_DIVISION_STATIC_COMPANIES } from '@/app/features/audits/organization/sub-divisions/sub-division-static-data';
import { CLIENT_MODE_VALUE } from '@/app/core/config/client-mode';
import { SCOPE_INDI_ORG_COMPANIES } from './audit-scope-static-indi-org.data';
import { MOCK_SCOPE_LIBRARY } from '@/app/features/audits/libraries/audit-scope-library/audit-scope-library-static-data';
import type {
  CompanyMeta,
  ScopeType,
  AuditFrequency,
  ModeOfAudit,
  SamplingMethodology,
  ScopeRiskRating,
  ScopeRecordStatus,
  ScopeStatus,
  StaticScope,
  StaticCompany,
} from './models/audit-scope.model';

/* ── Shared option lists ──────────────────────────────────────────────────
 * Single source of truth for the Add/Edit Audit Scope form
 * (add-audit-scope.component.ts) — previously a mix of the disconnected
 * org-hierarchy.ts (fake companies/divisions/sub-divisions) and small hardcoded
 * arrays (4 auditors, 4 reviewers whose ids didn't even match
 * REVIEWER_PROFILES). Auditor/Reviewer options are derived from the real
 * profile maps in divisions.ts so ids always match what scope-profile.component
 * (the view drawer) expects.
 */
export const SCOPE_TYPE_OPTIONS: { label: string; value: ScopeType }[] = [
  { label: 'Sub-Divisional', value: 'subDivisional' },
  { label: 'Functional', value: 'functional' },
  { label: 'Independent', value: 'independent' },
];

export const AUDIT_FREQUENCY_OPTIONS: { label: string; value: AuditFrequency }[] = [
  { label: 'Quarterly', value: 'quarterly' },
  { label: 'Annually', value: 'annually' },
  { label: 'Monthly', value: 'monthly' },
];

export const MODE_OF_AUDIT_OPTIONS: { label: string; value: ModeOfAudit }[] = [
  { label: 'Full', value: 'full' },
  { label: 'Limited', value: 'limited' },
  { label: 'Thematic', value: 'thematic' },
  { label: 'Follow-up', value: 'follow-up' },
  { label: 'Continuous', value: 'continuous' },
];

export const SAMPLING_METHODOLOGY_OPTIONS: { label: string; value: SamplingMethodology }[] = [
  { label: 'Random', value: 'random' },
  { label: 'Risk-based', value: 'risk-based' },
  { label: 'Judgmental', value: 'judgmental' },
];

export const RISK_RATING_OPTIONS: { label: string; value: ScopeRiskRating }[] = [
  { label: 'Low', value: 'low' },
  { label: 'Medium', value: 'medium' },
  { label: 'High', value: 'high' },
];

export const HOURLY_RATE_OPTIONS: { label: string; value: number }[] = [
  { label: '$50/hr', value: 50 },
  { label: '$75/hr', value: 75 },
  { label: '$100/hr', value: 100 },
  { label: '$150/hr', value: 150 },
];

export const AUDITOR_OPTIONS: { label: string; value: string }[] =
  Object.values(AUDITOR_PROFILES).map(p => ({ label: p.displayName, value: p.id }));

export const REVIEWER_OPTIONS: { label: string; value: string }[] =
  Object.values(REVIEWER_PROFILES).map(p => ({ label: p.displayName, value: p.id }));

