/**
 * The live scope roster every consumer imports. Which seed backs it depends
 * on CLIENT_MODE_VALUE — the multi-company audit-firm roster above, or the
 * single-org DAR Exchange AML/CFT Compliance seed in
 * audit-scope-static-indi-org.data.ts. Read at module scope (not via DI),
 * same reasoning as DIVISION_STATIC_COMPANIES in division-static-data.ts: this
 * array is imported directly by other modules and mutated in place by the
 * helpers below, so it has to be the right array before any of them
 * evaluate.
 */
export const AUDIT_SCOPE_STATIC_COMPANIES: StaticCompany[] =
  CLIENT_MODE_VALUE === 'internal-audit' ? SCOPE_INDI_ORG_COMPANIES : AUDIT_FIRM_SCOPE_COMPANIES;

/** Reads the REAL division list (division-static-data.ts) — not this file's own
 *  scope-grouping wrapper array — so a division added via divisions.ts's Add
 *  Division flow is selectable here immediately, even before it has any scopes. */
export function divisionOptionsForCompany(
  companyId: string | null | undefined,
  opts?: { companyBlocked?: boolean; includeDivisionCode?: string | null },
): { label: string; value: string }[] {
  const company = DIVISION_STATIC_COMPANIES.find(c => c.id === companyId);
  if (!company) return [];
  return company.divisions
    .filter(b => (b.status === 'active' && !opts?.companyBlocked) || b.divisionCode === opts?.includeDivisionCode)
    .map(b => ({ label: b.divisionName, value: b.divisionCode }));
}

/** Reads the REAL sub-division list (sub-division-static-data.ts) — not this
 *  file's own scope-grouping wrapper array — so a sub-division added via
 *  sub-divisions.ts's Add Sub-Division flow is selectable here immediately, even
 *  before it has any scopes (no scopes-count filter — you must be able to
 *  pick a sub-division with zero scopes to add its first one). */
export function subDivisionOptionsForDivision(
  companyId: string | null | undefined,
  divisionCode: string | null | undefined,
  opts?: { includeSubDivisionName?: string | null },
): { label: string; value: string }[] {
  const division = SUB_DIVISION_STATIC_COMPANIES
    .find(c => c.id === companyId)?.divisions
    .find(b => b.divisionCode === divisionCode);
  if (!division) return [];
  return division.subDivisions
    .filter(d => d.status === 'active' || d.subDivisionName === opts?.includeSubDivisionName)
    .map(d => ({ label: d.subDivisionName, value: d.subDivisionName }));
}

/**
 * Whether a division takes its scopes under its sub-divisions — the live
 * `hasSubDivision` flag (division-static-data.ts) AND at least one selectable
 * sub-division. When false, scopes are created directly under the division.
 */
export function divisionHasSubDivisions(
  companyId: string | null | undefined,
  divisionCode: string | null | undefined,
): boolean {
  const division = DIVISION_STATIC_COMPANIES
    .find(c => c.id === companyId)?.divisions
    .find(b => b.divisionCode === divisionCode);
  debugger;
  return !!division?.hasSubDivision && subDivisionOptionsForDivision(companyId, divisionCode).length > 0;
}

/** `subDivisionCode`s of every sub-division under a division — a division-level scope's `subDivisionsInfo`. */
export function subDivisionCodesForDivision(
  companyId: string | null | undefined,
  divisionCode: string | null | undefined,
): string[] {
  return SUB_DIVISION_STATIC_COMPANIES
    .find(c => c.id === companyId)?.divisions
    .find(b => b.divisionCode === divisionCode)?.subDivisions
    .map(d => d.subDivisionCode) ?? [];
}

/**
 * Real, sub-division-scoped Parent Scope options for the "fresh" (non-library)
 * Add/Edit flow — only top-level scopes (`parentScopeId === null`) in the
 * exact company/division/sub-division selected are offered, and `excludeId`
 * keeps a scope from being selected as its own parent while editing.
 * Sub-scopes are never offered here, so a sub-scope can never itself become
 * a parent.
 */
export function topLevelScopeOptionsForSubDivision(
  companyId: string | null | undefined,
  divisionCode: string | null | undefined,
  subDivisionName: string | null | undefined,
  excludeId?: string | null,
  opts?: { includeScopeId?: string | null },
): { label: string; value: string }[] {
  const container = findScopeContainer(companyId, divisionCode, subDivisionName);
  if (!container) return [];
  return container.scopes
    .filter(s => s.parentScopeId === null && s.id !== excludeId)
    .filter(s => s.status === 'active' || s.id === opts?.includeScopeId)
    .map(s => ({ label: s.scopeName, value: s.id }));
}

/**
 * Flat, company-unscoped list of every scope AND sub-scope across every company/division/
 * sub-division — mirrors rfi-static-data.ts's getAllEnrichedRfis() for consumers (like the
 * client-facing Audit Scope Summary page) that pool every company together rather than
 * drill down company-by-company the way the Admin Scope Management page's own drawers do
 * via findStaticScopeById()/subScopesOf() below.
 */
export function getAllStaticScopes(): StaticScope[] {
  return allScopeContainers().flatMap(c => c.scopes);
}

/**
 * Every `scopes[]` holder in the tree — each division (its division-level
 * scopes) and each of its sub-divisions — so lookups below cover both levels.
 */
function allScopeContainers(): { scopes: StaticScope[] }[] {
  const out: { scopes: StaticScope[] }[] = [];
  for (const company of AUDIT_SCOPE_STATIC_COMPANIES) {
    for (const division of company.divisions) {
      out.push(division, ...division.subDivisions);
    }
  }
  return out;
}

/** The division (when `subDivisionName` is empty — division-level scopes) or sub-division holding scopes. */
function findScopeContainer(
  companyId: string | null | undefined,
  divisionCode: string | null | undefined,
  subDivisionName: string | null | undefined,
): { scopes: StaticScope[] } | undefined {
  const division = AUDIT_SCOPE_STATIC_COMPANIES
    .find(c => c.id === companyId)?.divisions
    .find(b => b.divisionCode === divisionCode);
  if (!division) return undefined;
  return subDivisionName ? division.subDivisions.find(d => d.subDivisionName === subDivisionName) : division;
}

/** Flat search across every company/division/sub-division for a scope or sub-scope by id. */
export function findStaticScopeById(id: string | null | undefined): StaticScope | undefined {
  if (!id) return undefined;
  for (const container of allScopeContainers()) {
    const scope = container.scopes.find(s => s.id === id);
    if (scope) return scope;
  }
  return undefined;
}

/**
 * Resolves a Scope Library item id (`sl-*` / `ssl-*` from MOCK_SCOPE_LIBRARY)
 * to its real scope/sub-scope. The Add RFI drawer's "From RFI Library" mode
 * fills its Audit Scope/Sub-Scope dropdowns from the library, and library and
 * real scopes share no ids — only names — so the match is by company/branch/
 * department/title (and, for a sub-scope, the parent scope's title).
 * Use findStaticScopeById() for real scope ids.
 */
export function findStaticScopeByLibraryId(libraryId: string | null | undefined): StaticScope | undefined {
  if (!libraryId) return undefined;
  const item = MOCK_SCOPE_LIBRARY.find(l => l.id === libraryId);
  if (!item) return undefined;
  const dept = AUDIT_SCOPE_STATIC_COMPANIES
    .find(c => c.id === item.company)?.divisions
    .find(b => b.divisionCode === item.division)?.subDivisions
    .find(d => d.subDivisionName === item.subDivision);
  if (!dept) return undefined;
  return dept.scopes.find(s => {
    if (s.scopeName !== item.title) return false;
    if (item.scopeLevel === 'scope') return s.parentScopeId === null;
    return s.parentScopeId !== null
      && dept.scopes.find(p => p.id === s.parentScopeId)?.scopeName === item.parentScopeTitle;
  });
}

/** All sub-scopes (flat sibling records with parentScopeId === parentId) of a top-level scope. */
export function subScopesOf(parentId: string): StaticScope[] {
  return getAllStaticScopes().filter(scope => scope.parentScopeId === parentId);
}

function nextScopeId(): string {
  let max = 0;
  for (const scope of getAllStaticScopes()) {
    const n = parseInt(scope.id.replace('SC-', ''), 10);
    if (!isNaN(n) && n > max) max = n;
  }
  return `SC-${String(max + 1).padStart(4, '0')}`;
}

/* ── Mutations ────────────────────────────────────────────────────────────
 * There's no backend behind this page — the Add/Edit Audit Scope drawer
 * writes straight into this in-memory array so audit-scope-management.html
 * reflects additions/edits immediately. Add and edit are separate
 * operations: adding always appends a brand-new scope/sub-scope (a
 * generated id, so it's never confused with an existing one); editing
 * merges in place instead of remove-then-append, so the row doesn't jump
 * to the bottom of its sub-division.
 */

/**
 * Adds a brand-new scope or sub-scope under `companyId`/`divisionCode`/
 * `subDivisionName` — whether it's a scope or a sub-scope is entirely
 * determined by `fields.parentScopeId` (null vs. an existing top-level
 * scope's id). Always starts the scope at `workflowStatus: 'Pending Review'`
 * — the Add/Edit Audit Scope form has no control for it, so every new
 * scope/sub-scope has to clear the Scope Requests approval queue before
 * it's considered live (mirrors `upsertStaticDivision`/`upsertStaticSubDivision`).
 */
export function upsertStaticScope(
  companyId: string,
  divisionCode: string,
  /** null/empty adds a division-level scope. */
  subDivisionName: string | null,
  fields: Omit<StaticScope, 'id'>,
  companyMeta?: CompanyMeta,
): StaticScope | undefined {
  debugger;
  let company = AUDIT_SCOPE_STATIC_COMPANIES.find(c => c.id === companyId);
  if (!company) {
    company = {
      id: companyId,
      companyName: companyMeta?.companyName ?? companyId,
      tag: companyMeta?.tag ?? companyId.slice(0, 3).toUpperCase(),
      color: companyMeta?.color ?? '#102e70',
      divisions: [],
    };
    AUDIT_SCOPE_STATIC_COMPANIES.push(company);
  }
  let division = company.divisions.find(b => b.divisionCode === divisionCode);
  if (!division) {
    const realDivision = DIVISION_STATIC_COMPANIES
      .find(c => c.id === companyId)?.divisions
      .find(b => b.divisionCode === divisionCode);
    division = { divisionCode, divisionName: realDivision?.divisionName ?? divisionCode, hasSubDivision: realDivision?.hasSubDivision ?? false, company: companyId, scopes: [], subDivisions: [] };
    company.divisions.push(division);
  }
  let container: { scopes: StaticScope[] } = division;
  if (subDivisionName) {
    let dept = division.subDivisions.find(d => d.subDivisionName === subDivisionName);
    if (!dept) {
      dept = { subDivisionName, company: companyId, divisionCode, scopes: [] };
      division.subDivisions.push(dept);
    }
    container = dept;
  }
  // Always stamp a fresh id/createdAt here — the caller's `fields.createdAt`
  // (if any) is ignored, so a newly-added scope always sorts to the top of
  // the newest-first list regardless of what the form happened to send.
  const scope: StaticScope = { ...fields, hasSubDivision: !!subDivisionName, workflowStatus: 'Pending Review', id: nextScopeId(), createdAt: new Date().toISOString() };
  container.scopes.push(scope);
  return scope;
}

/**
 * Updates the scope/sub-scope previously identified by `id`, merging in
 * `updates` (the form's fields, including a possibly-changed
 * `parentScopeId`) onto the existing record. If `updates.company`/
 * `divisionCode`/`subDivisionName` still point at the record's current
 * sub-division, it's replaced in place (keeping its position); otherwise it's
 * moved to the new sub-division's `scopes[]`.
 */
export function editStaticScope(id: string, updates: Omit<StaticScope, 'id'>): void {
  for (const container of allScopeContainers()) {
    const idx = container.scopes.findIndex(s => s.id === id);
    if (idx === -1) continue;

    const merged: StaticScope = { ...container.scopes[idx], ...updates, id };
    if (updates.subDivisionName !== undefined) merged.hasSubDivision = !!updates.subDivisionName;
    const target = findScopeContainer(updates.company, updates.divisionCode, updates.subDivisionName);
    if (!target) return;

    if (target === container) {
      container.scopes[idx] = merged;
    } else {
      container.scopes.splice(idx, 1);
      target.scopes.push(merged);
    }
    return;
  }
}

/** Sets a scope/sub-scope's `status` in place (used by the Activate/Deactivate action). */
export function setScopeStatus(id: string, status: ScopeRecordStatus): void {
  const scope = findStaticScopeById(id);
  if (scope) scope.status = status;
}

/** Sets a scope/sub-scope's `workflowStatus` in place (used by the approval workflow actions). */
export function setScopeWorkflowStatus(id: string, status: ScopeStatus): void {
  const scope = findStaticScopeById(id);
  if (scope) scope.workflowStatus = status;
}